@@ -0,0 +1,40 @@
+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+const read=n=>JSON.parse(readFileSync(new URL(n,import.meta.url),'utf8'));
+
+const official=[...read('official-editions-01.json').rows,...read('official-editions-02.json').rows];
+const dates=read('law-effective-dates.json');
+const regulations=read('local-regulations-14.json');
+const decisions=read('selected-decisions-18.json');
+const pdfs=read('local-binary-hashes.json');
+const previous=read('../ni-adm131-20261024/local-inventory-summary.json');
+
+assert.equal(official.length,14);
+assert.equal(new Set(official.map(x=>x.id)).size,14);
+assert.ok(official.every(x=>x.public_html_accessible && x.original_pdf_download_restricted));
+assert.ok(official.every(x=>x.signed_original_pdf_saved===false && x.sha256_signed_original===null));
+assert.ok(official.every(x=>x.operative_article1_fully_certified===false && x.border_or_parent_change_certified===false));
+assert.equal(dates.rows.length,14);
+assert.deepEqual(new Set(dates.rows.map(x=>x.publication_id)),new Set(official.map(x=>x.id)));
+assert.equal(dates.counts.NEXT_DAY_AFTER_OFFICIAL_PUBLICATION,7);
+assert.equal(dates.counts.FIXED_COMMENCEMENT,4);
+assert.equal(dates.counts.CONDITIONAL_COMMENCEMENT,3);
+assert.equal(dates.legal_effects.three_conditional_acts_unadjudicated,3);
+assert.equal(dates.legal_effects.fully_certified_article1_changes,0);
+assert.ok(dates.rows.filter(x=>x.condition_unresolved).every(x=>x.derived_effective_date===null));
+assert.ok(dates.rows.every(x=>x.territorial_boundaries_effect_certified===false));
+assert.equal(regulations.records.length,14);
+assert.equal(regulations.records.filter(x=>x.content_read).length,11);
+assert.equal(regulations.no_text_returned,3);
+assert.equal(decisions.rows.length,18);
+assert.equal(decisions.rows.filter(x=>x.readable).length,15);
+assert.equal(decisions.rows.filter(x=>!x.readable).length,3);
+assert.ok(decisions.rows.every(x=>x.de_facto_polygon_boundary_change_accepted===false));
+assert.equal(pdfs.examples.length,2);
+assert.deepEqual(pdfs.examples.map(x=>x.source_bytes),[808115,494587]);
+assert.ok(pdfs.examples.every(x=>/^[0-9a-f]{64}$/.test(x.original_raw_sha256) && x.qualified_signature_authenticated===false));
+assert.equal(pdfs.global_originals_recovered_from_14_central_laws,0);
+assert.equal(previous.unique_files,307);
+assert.equal(previous.P9_1,'BLOCKED');
+assert.equal(previous.protected_ACTUAL_unchanged,true);
+console.log('PASS scoped NI-ADM.1.3.2: 14 official editions, 11 unconditional dates, 3 blocked triggers, 26 local readable texts');
